const FONT_MIME_TYPES = new Map([
	["woff2", "font/woff2"],
	["woff", "font/woff"],
	["ttf", "font/ttf"],
	["otf", "font/otf"],
	["eot", "application/vnd.ms-fontobject"]
]);





const fontMimeType = (request) => {
	const match = /\.([a-z0-9]+)(?:[?#]|$)/i.exec(request);
	return match ? FONT_MIME_TYPES.get(match[1].toLowerCase()) : undefined;
};








